SELECT p.id, p.merchant_id, p.category_id, p.name, p.description, p.main_image, p.images, p.price_min, p.price_max, p.sales_count, p.status, p.created_at, c.id AS c_id, c.name AS c_name, c.parent_id AS c_parent_id, c.sort_order AS c_sort_order FROM products p LEFT JOIN categories c ON p.category_id = c.id WHERE p.id IN
#{pid}
ORDER BY p.id

SELECT id FROM products
WHERE category_id = #{categoryId}
ORDER BY id
LIMIT #{limit}
